class _Tester<T> extends SingleChildRenderObjectWidget {
  const _Tester({Key? key, required this.value, required Widget child})
      : super(key: key, child: child);
  final T value;
  @override
  _RenderTester<T> createRenderObject(BuildContext context) => _RenderTester<T>(value: value);
  @override
  void updateRenderObject(BuildContext context, _RenderTester<T> renderObject) {
    renderObject.value = value;
  }
}

_Tester<String>(
  value: 'test',
  child: ValueLayoutBuilder<String>(
    builder: (context, constraints) {
      final String value = constraints.value;
      return Text(value);
    },
  ),
)
